func (q *Queries) RolesDeUsuarios(ctx context.Context, usuarios []int64) ([]RolesDeUsuariosRow, error) {
	rows, err := q.db.Query(ctx, rolesDeUsuarios, usuarios)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RolesDeUsuariosRow
	for rows.Next() {
		var i RolesDeUsuariosRow
		if err := rows.Scan(
			&i.UsuarioID,
			&i.ZonaID,
			&i.CuadrillaID,
			&i.Codigo,
			&i.Nombre,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

